 private JsonNode intentWitness(ConnectionVerificationMapper.Intent i)throws IOException{var n=(com.fasterxml.jackson.databind.node.ObjectNode)json.tree(i);n.put("request_json",canonical(schemaRead(i.requestJson())));n.put("created_at",Instant.parse(i.createdAt()).toString());return json.tree(Map.of("schema_version","1.0.0","verification_id",i.verificationId(),"intent_sha256",hash(n)));}
